/**
 * We set up values outside of the static class to keep their values private.
 */

let mediaQuery = null;
const listeners = new Set();

/**
 * Media query handler when the query is re-evaluated.
 */
function handleQueryUpdate(query) {
  const isMobile = query.matches;

  // Update our listeners, but carefully update as to not trigger reflows if
  // not needed.
  listeners.forEach(listener => {
    if (listener.isMobile !== isMobile) listener.isMobile = isMobile;
  });
}

/**
 * Starts up the MobileManager media query watching the window.
 */
function init() {
  if (mediaQuery) return;
  mediaQuery = window.matchMedia(`(min-width: 0px) and (max-width: 768px)`);
  handleQueryUpdate(mediaQuery);
  mediaQuery.addListener(handleQueryUpdate);
}

/**
 * Removes the media query listener and stops the MobileManager's operations
 * entirely.
 */
function stop() {
  if (!mediaQuery) return;
  mediaQuery.removeListener(handleQueryUpdate);
  listeners.clear();
  mediaQuery = null;
}

/**
 * This is a helper class to simplify components waiting for the application to
 * be within mobile dimensions. This is inflexible as it normalizes what
 * 'mobile' means to the same screen width across all components that use this.
 * You should use the <MobileOnly> <DesktopOnly> components if you need finer
 * control.
 */
export class MobileManager {
  /**
   * A component can be a listener simply if it has a 'isMobile' property on it.
   * Use this in the components beforeMount method.
   */
  static addListener(component) {
    init();
    if (listeners.has(component)) return true;
    listeners.add(component);
    component.isMobile = mediaQuery.matches;
    return false;
  }

  /**
   * Remove a listening component using this. You should remove the listener in
   * the components beforeDestroy method.
   */
  static removeListener(component) {
    const result = listeners.delete(component);
    if (listeners.size === 0) stop();
    return result;
  }
}
